css:
html {
  color-scheme: light;
  background: var(--va-color-surface-default);
  color: var(--va-color-text-default);
  font-family: var(--va-font-family-ui);
  transition:
    background-color var(--va-motion-duration-slow),
    color var(--va-motion-duration-slow);
}

html[data-va-mode="dark"] {
  color-scheme: dark;
}

@media (prefers-reduced-motion: reduce) {
  html {
    transition: none;
  }
}

.appearance {
  max-width: 40rem;
  margin-inline: auto;
  padding: var(--va-space-inline-lg);
}

.appearance h1 {
  font-family: var(--va-font-family-reading);
  font-weight: var(--va-font-weight-bold);
  margin-block: 0 var(--va-space-inline-sm);
}

.intro {
  color: var(--va-color-text-muted);
  margin-block: 0 var(--va-space-inline-lg);
}

.setting {
  padding: var(--va-space-inline-md) var(--va-space-inline-lg);
  border: 1px solid var(--va-color-border-subtle);
  border-radius: var(--va-radius-surface);
  background: var(--va-color-surface-subtle);
}

.status {
  color: var(--va-color-text-muted);
  font-size: var(--va-font-size-sm);
  margin-block: var(--va-space-inline-sm) 0;
}

js:
const STORAGE_KEY = 'va-theme-mode';
const root = document.documentElement;
const toggle = document.getElementById('dark-theme-switch');
const status = document.getElementById('theme-status');
const systemDark = window.matchMedia('(prefers-color-scheme: dark)');

function readSaved() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved === 'dark' || saved === 'light' ? saved : null;
  } catch {
    return null;
  }
}

function save(mode) {
  try {
    localStorage.setItem(STORAGE_KEY, mode);
  } catch {
    /* Storage unavailable: the choice still applies for this visit. */
  }
}

function applyMode(mode) {
  root.setAttribute('data-va-mode', mode);
  toggle.checked = mode === 'dark';
}

// Start from the saved choice, else the page's existing mode, else the system setting.
const current = root.getAttribute('data-va-mode');
const initial =
  readSaved() ??
  (current === 'dark' || current === 'light' ? current : systemDark.matches ? 'dark' : 'light');
applyMode(initial);

toggle.addEventListener('change', (event) => {
  const mode = event.target.checked ? 'dark' : 'light';
  applyMode(mode);
  save(mode);
  status.textContent = mode === 'dark' ? 'Dark theme on.' : 'Dark theme off.';
});

// Until the user makes a choice, follow changes to the system setting.
systemDark.addEventListener('change', (event) => {
  if (readSaved() === null) applyMode(event.matches ? 'dark' : 'light');
});
